WITH agg AS ( SELECT cd.cd_gender, cd.cd_education_status, SUM(ss.ss_net_profit) AS total_net_profit, SUM(ss.ss_ext_sales_price) AS total_sales, AVG(ss.ss_ext_discount_amt / NULLIF(ss.ss_ext_sales_price,0)) AS avg_discount_ratio, COUNT(DISTINCT ss.ss_customer_sk) AS distinct_customers, ib.ib_lower_bound, ib.ib_upper_bound FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk WHERE ib.ib_upper_bound >= 100000 GROUP BY cd.cd_gender, cd.cd_education_status, ib.ib_lower_bound, ib.ib_upper_bound ) SELECT cd_gender, cd_education_status, total_net_profit, total_sales, avg_discount_ratio, distinct_customers, CASE WHEN total_net_profit < 0 THEN 'Loss' WHEN total_net_profit BETWEEN 0 AND 50000 THEN 'Low' WHEN total_net_profit BETWEEN 50001 AND 200000 THEN 'Medium' ELSE 'High' END AS profit_category, RANK() OVER (PARTITION BY cd_gender ORDER BY total_net_profit DESC) AS profit_rank_by_gender FROM agg ORDER BY cd_gender, profit_rank_by_gender
